window.MOTIF_CATALOG_CHUNKS[34]={"cards":[{"id":"MEJE-KW-001173","row_version":2,"title":"음주가 성적 지향을 바꾼 듯 그리기","original":"Alcohol-Induced Bisexuality","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"평소와 다른 상대에게 끌리는 모습을 술 탓으로만 처리하는 이야기 관습. 성적 지향을 일시적 장난으로 축소하는 표현인지, 인물의 원래 마음을 드러내는 장면인지 구분해 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001173/index.html"},{"id":"MEJE-KW-001174","row_version":2,"title":"음주 뒤 무모한 행동","original":"Alcohol-Induced Idiocy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"술을 마신 인물이 평소라면 하지 않을 성급한 선택을 해 사건을 키우는 흐름. 행동의 결과와 책임을 어떻게 다루는지가 웃음과 비판의 방향을 정한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001174/index.html"},{"id":"MEJE-KW-001175","row_version":3,"title":"술을 연료처럼 쓰는 허구적 장면","original":"Alcohol Is Gasoline","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"술을 기계의 연료로 부어 작동하게 하거나 지나치게 강한 술을 연료에 빗대는 과장된 표현. 실제 사용법이 아니라 허구의 농담과 세계관 관습으로 설명한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001175/index.html"},{"id":"MEJE-KW-000072","row_version":2,"title":"동행인을 지위의 장식처럼 과시","original":"A Lady on Each Arm","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 양옆의 동행인을 자신의 인기나 지위를 보여 주는 장식처럼 데리고 등장하는 연출. 등장 장면 하나로 허영이나 권력관을 드러내지만, 동행인의 인격을 지우는 대상화가 함께 나타날 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-000072/index.html"},{"id":"MEJE-KW-001176","row_version":2,"title":"시공간 굴절 항행","original":"Alcubierre Drive","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17","ML-T01490","ML-T01492"],"summary":"우주선 자체의 속도를 높이는 대신 주변 시공간의 형태를 바꾸어 먼 거리를 건넌다는 가상 항행 방식. 작품에서는 이동 거리와 시간의 제약을 완화하는 설정 장치로 쓰인다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"초고속 이동","entry_url":"cards/MEJE-KW-001176/index.html"},{"id":"MEJE-KW-001177","row_version":1,"title":"눈치챔의 번쩍임","original":"Alertness Blink","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 무언가를 알아차리는 순간 짧은 빛, 기호 또는 소리를 덧붙이는 연출. 내면의 인지 변화를 대사 없이 즉각 전달한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001177/index.html"},{"id":"MEJE-KW-001178","row_version":2,"title":"수치 누적형 서사 분기","original":"Algorithmic Story Branching","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02125","ML-T02126"],"summary":"개별 선택 하나보다 여러 행동에서 쌓인 수치나 성향을 판정해 후속 사건을 고르는 이야기 구조. 같은 장면도 이전 선택의 누적 결과에 따라 다른 의미로 이어질 수 있다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"분기 선택","entry_url":"cards/MEJE-KW-001178/index.html"},{"id":"MEJE-KW-001179","row_version":2,"title":"앨리스 모티프 인용","original":"Alice Allusion","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"이상한 나라의 앨리스를 떠올리게 하는 이름, 토끼굴, 카드나 거울 같은 표지를 통해 낯선 세계로의 진입을 암시하는 참조 방식. 단순한 이름 일치와 구분해 작품의 이미지가 실제로 서사에 작용하는지 본다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001179/index.html"},{"id":"MEJE-KW-001180","row_version":1,"title":"앨리스와 밥의 가상 대화자","original":"Alice and Bob","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"추상적인 규칙이나 상황을 설명할 때 두 가상 인물에게 역할을 나누어 주는 서술 관습. 인물 자체의 전기보다 누가 무엇을 알고 전달하는지를 명료하게 만드는 데 쓰인다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001180/index.html"},{"id":"MEJE-KW-001181","row_version":1,"title":"외계 납치 피해자의 반격","original":"Alien Abductees Fight Back","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00780"],"summary":"외계 존재에게 붙잡힌 인물이 탈출이나 협력을 통해 가해자에게 맞서는 전개. 외계 존재의 납치가 무력감에 초점을 두었다면 이 카드는 주도권을 되찾는 행동에 초점을 둔다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"납치","entry_url":"cards/MEJE-KW-001181/index.html"},{"id":"MEJE-KW-001182","row_version":2,"title":"외계 존재의 납치","original":"Alien Abduction","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00780"],"summary":"외계 존재가 인간이나 다른 생명체를 뜻밖에 데려가 행방과 목적을 알 수 없게 만드는 사건. 귀환 이후 기억의 공백, 불신, 접촉의 비대칭이 이야기를 이끈다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"납치","entry_url":"cards/MEJE-KW-001182/index.html"},{"id":"MEJE-KW-001183","row_version":1,"title":"정체를 숨기고 함께 사는 외계인","original":"Alien Among Us","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01148","ML-T01149"],"summary":"외계에서 온 존재가 일상 사회에 섞여 살면서 자신의 출신을 감추는 설정. 발견될 위험과 낯선 관습을 배우는 과정이 관계와 갈등을 만든다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"외계 생명","entry_url":"cards/MEJE-KW-001183/index.html"},{"id":"MEJE-KW-001184","row_version":1,"title":"지구 동물의 외계 기원","original":"Alien Animals","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01148","ML-T01149"],"summary":"익숙한 지구 동물 한 종 또는 그 전체가 사실 다른 세계에서 왔다는 반전. 평범한 생태를 바라보던 시각이 한순간에 낯선 세계의 단서로 바뀐다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"외계 생명","entry_url":"cards/MEJE-KW-001184/index.html"},{"id":"MEJE-KW-001185","row_version":1,"title":"종을 넘어 향유되는 외계 예술","original":"Alien Arts Are Appreciated","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01391"],"summary":"감각과 문화가 다른 존재가 만든 예술을 다른 종도 이해하거나 즐기는 설정. 감상 방식의 차이와 번역의 한계가 교류 장면을 풍부하게 만든다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"문화·규범","entry_url":"cards/MEJE-KW-001185/index.html"},{"id":"MEJE-KW-001186","row_version":2,"title":"외계 생명체의 부검","original":"Alien Autopsy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"죽은 외계 생명체의 몸을 조사하며 그 존재의 구조와 비밀을 드러내는 사건. 진실 규명의 기대와 당사자에 대한 존중, 정보 통제의 갈등이 함께 따를 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001186/index.html"},{"id":"MEJE-KW-001187","row_version":2,"title":"외계인에게만 취기를 일으키는 물질","original":"Alien Catnip","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인간에게는 평범한 음식이나 물질이 다른 종에게는 강한 취기 또는 의존을 일으킨다는 설정. 생리 차이를 보여 주는 동시에 무심한 접촉이 예기치 않은 결과를 낳게 한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001187/index.html"},{"id":"MEJE-KW-001188","row_version":1,"title":"외계 행성의 공룡형 생명","original":"Alien Dinosaurs","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01148","ML-T01149"],"summary":"먼 행성의 동물이 지구의 고생물과 닮은 모습으로 제시되는 설정. 독자가 낯선 생태를 빠르게 알아보게 하지만 동일한 진화 과정을 전제하는 설명과는 구분할 필요가 있다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"외계 생명","entry_url":"cards/MEJE-KW-001188/index.html"},{"id":"MEJE-KW-001189","row_version":2,"title":"갑작스러운 외계 방문 에피소드","original":"Alien Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"평소 외계 존재가 등장하지 않는 연속물에 외계 방문 사건이 한 회차만 끼어드는 구성. 일상적 작품 규칙을 잠시 흔들어 놀라움이나 장르 변주를 만든다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001189/index.html"},{"id":"MEJE-KW-001190","row_version":1,"title":"외계인과 요정 전승의 동일시","original":"Alien Fair Folk","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"옛 전승의 요정이나 초자연 존재를 외계 방문자로 읽거나, 현대의 외계 목격담을 오래된 전승의 새 모습으로 해석하는 설정. 이는 허구의 해석 장치이며 실제 전승의 사실 여부를 판정하지 않는다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001190/index.html"},{"id":"MEJE-KW-001191","row_version":1,"title":"종족 간 성별 오인","original":"Alien Gender Confusion","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01391"],"summary":"서로 다른 종의 구성원이 상대 종의 성별이나 사회적 호칭을 자기 기준으로 추정하다 빗나가는 상황. 외형과 역할을 동일시하는 편견 자체를 드러내는 방식으로도 쓸 수 있다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"문화·규범","entry_url":"cards/MEJE-KW-001191/index.html"},{"id":"MEJE-KW-001192","row_version":1,"title":"현실 규칙을 벗어난 공간 기하","original":"Alien Geometries","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01321"],"summary":"익숙한 거리와 방향의 감각이 맞지 않는 공간 또는 건축 형상. 길이와 안팎의 관계가 어긋나며 세계의 낯섦과 불안을 체험하게 한다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"이계 공간","entry_url":"cards/MEJE-KW-001192/index.html"},{"id":"MEJE-KW-001193","row_version":1,"title":"외계인의 머리카락 도상","original":"Alien Hair","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"영상 속 외계 인물의 머리 모양이나 헤어라인으로 인간과의 차이를 빠르게 표시하는 시각 관습. 외형상의 차이가 종족 전체의 성격을 대신 설명하지 않도록 구분한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-001193/index.html"},{"id":"MEJE-KW-001194","row_version":2,"title":"외계 세력의 지구 침공","original":"Alien Invasion","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"외계 세력이 지구의 영역이나 제도를 장악하려 시도하면서 인류 사회 전체가 위기에 놓이는 사건. 공개 공격, 잠입, 협상의 실패 등 접근 방식에 따라 갈등의 성질이 달라진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001194/index.html"},{"id":"MEJE-KW-001195","row_version":2,"title":"외래 생명체의 생태계 점령","original":"Alien Kudzu","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"다른 세계에서 온 식물형 또는 고착 생명체가 빠르게 퍼져 현지 환경을 바꾸는 설정. 침공의 결과를 군사 충돌 밖의 생태 변화로 보여 준다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-001195/index.html"},{"id":"MEJE-KW-001196","row_version":1,"title":"낯선 지형으로 드러나는 외계 세계","original":"Alien Landmass","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"떠 있는 대지나 기이한 지층처럼 익숙한 땅의 형태를 바꾸어 다른 세계임을 알리는 환경 연출. 낯선 하늘로 드러나는 외계 세계·낯선 외계의 바다와 함께 장소의 성격을 만든다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-001196/index.html"},{"id":"MEJE-KW-001197","row_version":3,"title":"외계 문명 불간섭 원칙","original":"Alien Non-Interference Clause","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"다른 문명의 발전에 외부 세력이 기술이나 권력으로 개입하지 않도록 정한 세계관의 규칙. 보호를 위한 자제와 도움이 필요한 상황에서의 책임이 충돌할 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001197/index.html"},{"id":"MEJE-KW-001198","row_version":1,"title":"외계 왕족 여성","original":"Alien Princess","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00907","ML-T00908"],"summary":"다른 행성의 왕가에 속한 여성 인물이 낯선 정치 질서와 지구 인물의 관계를 연결하는 인물형. 왕족이라는 지위와 개인의 선택이 일치하지 않을 때 갈등이 생긴다.","accent":"#7B7594","tab":"#A58A4E","facet":"인물","bookmark":"왕족","entry_url":"cards/MEJE-KW-001198/index.html"},{"id":"MEJE-KW-001199","row_version":2,"title":"외계 종족의 일괄 악역화","original":"Aliens Are Bastards","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"외계 존재를 개별 인물이나 사회로 그리지 않고 모두 잔혹한 적으로 묶어 소비하는 표현 관습. 낯선 존재에 대한 공포를 쉽게 만들지만 종족 전체의 단일한 성격이라는 단순화도 낳는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001199/index.html"},{"id":"MEJE-KW-001200","row_version":1,"title":"낯선 외계의 바다","original":"Alien Sea","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"색, 성질, 해안의 형태가 지구의 바다와 다른 수역을 통해 장소의 이질성을 드러내는 환경 연출. 낯선 하늘로 드러나는 외계 세계·낯선 지형으로 드러나는 외계 세계와 맞물린다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-001200/index.html"},{"id":"MEJE-KW-001201","row_version":1,"title":"뜻밖의 평범한 장소를 사건의 중심에 놓기","original":"Aliens in Cardiff","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"대도시나 유명한 명소가 아닌 실제의 평범한 지역을 거대한 사건의 무대로 고르는 방식. 일상적인 장소와 비일상적인 사건의 간격이 놀라움을 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-001201/index.html"},{"id":"MEJE-KW-001202","row_version":1,"title":"낯선 하늘로 드러나는 외계 세계","original":"Alien Sky","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01313","ML-T01320"],"summary":"별과 달의 수, 빛깔이나 움직임을 바꾸어 인물이 다른 세계에 있음을 보여 주는 하늘 연출. 낯선 외계의 바다·낯선 지형으로 드러나는 외계 세계와 함께 환경의 첫인상을 만든다.","accent":"#68838D","tab":"#AF8665","facet":"시공간·환경","bookmark":"외계 행성","entry_url":"cards/MEJE-KW-001202/index.html"},{"id":"MEJE-KW-001203","row_version":2,"title":"외계인이 반하는 지구 음식","original":"Aliens Love Human Food","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01382","ML-T01383"],"summary":"외계 존재가 인간에게 평범한 음식을 특별한 즐거움으로 받아들이는 상황. 문화 교류의 작은 접점이 되거나 서로 다른 생리와 취향을 드러낸다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"식문화","entry_url":"cards/MEJE-KW-001203/index.html"},{"id":"MEJE-KW-001204","row_version":2,"title":"외부 세력이 강요하는 성적 관계","original":"Aliens Made Them Do It","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"두 인물의 친밀한 관계를 만들기 위해 외부 존재나 제도가 성적 행위를 명령·강요하는 서사 장치. 동의가 결여된 상황을 로맨스의 자연스러운 계기로 취급하지 않도록 경계를 분명히 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001204/index.html"},{"id":"MEJE-KW-001205","row_version":3,"title":"인간만 민주주의를 발명한 우주","original":"Aliens Never Invented Democracy","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01330"],"summary":"여러 문명 가운데 인간 사회만 선거와 대표 제도를 발전시켰다고 설정하는 세계관 관습. 종족마다 정치 체제가 하나뿐이라는 단순화를 피하면 비교의 의미가 살아난다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"정치·통치","entry_url":"cards/MEJE-KW-001205/index.html"},{"id":"MEJE-KW-001206","row_version":1,"title":"핵심 기술 하나가 없는 문명","original":"Aliens Never Invented the Wheel","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"다른 기술은 발달했지만 익숙한 발명 하나는 등장하지 않은 가상 문명. 발전의 순서가 모두 같아야 한다는 기대를 깨며 생활 방식의 차이를 드러낸다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001206/index.html"},{"id":"MEJE-KW-001207","row_version":1,"title":"외계인의 익숙한 억양","original":"Aliens of London","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01972"],"summary":"외계 존재가 인간 언어를 말할 때 배우의 지역 억양이나 관객에게 익숙한 발음으로 들리는 관습. 이야기 속 언어의 기원과 화면 밖 제작 조건이 만나는 지점이다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"문체·말투","entry_url":"cards/MEJE-KW-001207/index.html"},{"id":"MEJE-KW-001208","row_version":1,"title":"초현실적 개입으로 갈라진 가상역사","original":"Alien Space Bats","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"역사의 분기점에 외계 방문이나 초자연 사건을 넣어 현실적 가능성의 범위를 벗어난 대체 연표를 여는 방식. 우연의 작은 변화가 이어진 역사와는 출발 조건을 구분한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001208/index.html"},{"id":"MEJE-KW-001209","row_version":1,"title":"지구 방송으로 인간을 배운 외계인","original":"Aliens Steal Cable","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"외계 존재가 멀리 흘러간 지구 방송을 보고 인간 사회를 배웠다고 설정하는 이야기. 오래되거나 편향된 화면 정보와 실제 사람의 차이가 오해와 웃음을 만든다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001209/index.html"},{"id":"MEJE-KW-001210","row_version":3,"title":"외계인의 가축 납치","original":"Aliens Steal Cattle","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"외계 비행체가 농장의 가축을 데려가는 기이한 사건. 외계 접촉의 불안감을 유머와 결합하거나 목격담의 전형적 이미지로 사용된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001210/index.html"},{"id":"MEJE-KW-001211","row_version":4,"title":"가치 성향에 따른 결말","original":"Alignment-Based Endings","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02125","ML-T02132"],"summary":"플레이어가 쌓은 도덕적·정치적 성향이나 마지막 선택에 따라 결말을 나누는 게임 서사 구조. 단순한 승패보다 어떤 가치를 택했는지를 결과에 반영한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"다중 결말","entry_url":"cards/MEJE-KW-001211/index.html"},{"id":"MEJE-KW-001212","row_version":2,"title":"대립 집단의 다양성과 동질성 대비","original":"Alike and Antithetical Adversaries","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"서로 맞서는 집단의 구성원들이 얼마나 서로 다른지 또는 비슷한지를 대조해 갈등의 이미지를 만드는 방식. 겉모습의 다양성과 실제 관점의 다양성은 별도로 살펴야 한다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-001212/index.html"},{"id":"MEJE-KW-001213","row_version":2,"title":"학대 가해자를 남성으로만 그리는 관습","original":"All Abusers Are Male","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여러 작품이 학대와 폭력의 가해자를 남성으로만 반복해 그리면서 다른 가해·피해 관계를 보이지 않게 만드는 표현 관습. 한 작품의 개별 사건과 축적된 묘사 경향을 구분해 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001213/index.html"},{"id":"MEJE-KW-001214","row_version":1,"title":"모든 일이 계획대로였다는 선언","original":"All According to Plan","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01962"],"summary":"인물이 눈앞의 실패마저 자신의 계획 일부였다고 말해 사건의 해석을 뒤집는 대사 장치. 실제로 준비한 반전인지 허세인지는 뒤따르는 전개가 판정한다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"대사 기능","entry_url":"cards/MEJE-KW-001214/index.html"},{"id":"MEJE-KW-001215","row_version":3,"title":"여전사 사회가 남성 영웅을 선망한다는 관습","original":"All Amazons Want Hercules","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여성 중심의 전사 공동체도 결국 강한 남성 영웅 앞에서는 집단적으로 매료된다고 그리는 낡은 표현 관습. 구성원의 선택과 공동체의 질서를 한 인물에 대한 반응으로 단순화하는 효과를 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001215/index.html"},{"id":"MEJE-KW-001216","row_version":3,"title":"미국 상징을 내세운 선역 레슬러","original":"All-American Face","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"미국 국기 색과 애국적 구호를 활용해 관객의 응원을 이끌도록 만든 프로레슬링 인물형. 경기 안의 선악 구도와 국가 상징을 공연의 장치로 결합한다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-001216/index.html"},{"id":"MM-UNSET-000011","row_version":4,"title":"이상한 나라의 앨리스","original":"","aliases":[],"kind":"work","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02","ML-T00066","ML-T00067"],"summary":"《이상한 나라의 앨리스》는 루이스 캐럴이 쓴 1865년 판타지 소설로, 앨리스가 토끼 굴을 지나 논리와 규칙이 뒤집힌 세계를 여행하는 이야기다. 이 항목은 해당 작품을 가리키며, 작품의 영향을 받은 기묘한 모험이나 환상 세계 전반과 동일시하지 않는다.","accent":"#55758A","tab":"#9B765F","facet":"미디어","bookmark":"소설","entry_url":"cards/MM-UNSET-000011/index.html"},{"id":"MEJE-KW-001217","row_version":2,"title":"동물의 감정을 개처럼 표현하기","original":"All Animals Are Dogs","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"곰이나 다른 동물이 꼬리를 흔들거나 물건을 물어오는 등 개에게 익숙한 행동으로 감정을 드러내는 표현 관습. 관객은 감정을 쉽게 읽지만 종마다 다른 행동 방식은 희미해진다. 야생동물을 반려동물처럼 그리기와는 초점이 다르다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001217/index.html"},{"id":"MEJE-KW-001218","row_version":2,"title":"야생동물을 반려동물처럼 그리기","original":"All Animals Are Domesticated","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"야생동물이 처음 만난 사람에게도 쉽게 다가와 길든 반려동물처럼 행동하는 표현 관습. 친근한 동물 동료를 빠르게 만들지만 실제 야생동물과 사람의 거리감은 생략한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001218/index.html"},{"id":"MEJE-KW-001219","row_version":1,"title":"애니메이션을 한 회사 작품으로 오인하기","original":"All Animation Is Disney","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"제작사와 기법이 다른 애니메이션까지 익숙한 대형 제작사의 작품으로 생각하는 수용자의 인식. 매체의 다양성이 한 브랜드의 이미지에 가려지는 현상을 드러낸다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001219/index.html"},{"id":"MEJE-KW-001220","row_version":2,"title":"일본 애니메이션을 성인물로 일반화하기","original":"All Anime Is Naughty Tentacles","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"일부 자극적인 작품의 인상을 일본 애니메이션 전체에 덧씌우는 수용 관습. 장르와 연령대가 다양한 매체를 한 가지 이미지로 좁히는 편견을 설명한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001220/index.html"},{"id":"MEJE-KW-001221","row_version":1,"title":"위험을 직업의 일부로 받아들이기","original":"All a Part of the Job","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"반복되는 위협과 희생에도 맡은 일을 계속하는 인물이 그 위험까지 자신의 직업에 포함해 받아들이는 태도. 사명감, 숙련의 자부심, 모험에 대한 애착이 함께 작용할 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001221/index.html"},{"id":"MEJE-KW-001222","row_version":2,"title":"죽음 앞에서 지위가 지워지기","original":"All Are Equal in Death","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18","ML-T01612"],"summary":"죽음 이후에는 권력과 재산, 명예의 차이가 더는 인물을 구분하지 못한다는 주제. 단순히 모두 죽는다는 사실보다 사후의 대우나 의미까지 같아지는 데 초점을 둔다.","accent":"#7E8070","tab":"#A07A87","facet":"주제·가치","bookmark":"삶·죽음","entry_url":"cards/MEJE-KW-001222/index.html"},{"id":"MEJE-KW-001223","row_version":1,"title":"창작물을 작가의 삶으로 단정하기","original":"All Art Is Autobiographical","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"작품 안의 사건을 본 인물이 그 내용이 창작자의 실제 경험에서 왔다고 믿는 해석 습관. 허구와 개인사를 곧바로 등치하면서 오해나 반전을 낳는다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001223/index.html"},{"id":"MEJE-KW-001224","row_version":2,"title":"아시아인은 모두 무술을 안다는 고정관념","original":"All Asians Know Martial Arts","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 인물에게 출신만을 근거로 무술 실력을 부여하는 표현 관습. 개별 인물의 배경과 여러 문화의 차이를 지워 버리는 단순화로 다룬다. 중국인은 모두 쿵푸를 안다는 고정관념과 범위가 다르다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001224/index.html"},{"id":"MEJE-KW-001225","row_version":2,"title":"아시아인을 원뿔형 모자로 표시하는 관습","original":"All Asians Wear Conical Straw Hats","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여러 지역의 서로 다른 모자를 한 가지 시각 기호로 합쳐 아시아계 인물의 출신을 표시하는 표현 관습. 실제 복식의 용도와 지역 차이를 생략한 도상으로 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001225/index.html"},{"id":"MEJE-KW-001226","row_version":1,"title":"입김으로 불어도 뜨는 풍선","original":"All Balloons Have Helium","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"사람이 직접 불어 넣은 풍선이 가벼운 기체를 채운 것처럼 공중으로 떠오르는 만화적 표현. 물리적 개연성보다 움직임의 재미와 장면의 즉시성을 택한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001226/index.html"},{"id":"MEJE-KW-001227","row_version":3,"title":"판타지 세계의 맥주를 에일로 통일하기","original":"All Beer Is Ale","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01382","ML-T01383"],"summary":"과거풍 판타지의 맥주를 거의 모두 에일로 부르거나 그 모습으로 그리는 식문화 관습. 오래된 분위기를 빠르게 만들지만 다양한 술의 제조와 음용 문화를 단순화한다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"식문화","entry_url":"cards/MEJE-KW-001227/index.html"},{"id":"MEJE-KW-001228","row_version":2,"title":"오토바이 운전자를 폭력조직으로 단정하는 관습","original":"All Bikers Are Hells Angels","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"오토바이를 탄 인물을 곧바로 범죄 집단의 구성원으로 읽히게 하는 시청각 관습. 복장과 탈것의 이미지로 인물의 성격을 대신 설명하는 방식이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001228/index.html"},{"id":"MEJE-KW-001229","row_version":2,"title":"선사 인물을 하나의 원시인상으로 뭉뚱그리기","original":"All Cavemen Were Neanderthals","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"서로 다른 선사 시대와 인류를 힘세고 둔한 한 종류의 원시인 모습으로 합치는 표현 관습. 시대와 종의 차이를 지운 채 거친 몸짓과 빈약한 언어로 낯섦을 표시한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001229/index.html"},{"id":"MEJE-KW-001230","row_version":1,"title":"전편 컴퓨터 제작 애니메이션","original":"All-CGI Cartoon","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"화면의 움직이는 그림을 처음부터 끝까지 디지털 도구로 제작한 애니메이션 형식. 입체 그래픽뿐 아니라 디지털 이차원 작업도 포함할 수 있으므로 화면의 입체감과 제작 방식을 구분한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-001230/index.html"},{"id":"MEJE-KW-001231","row_version":2,"title":"일상에서도 응원 구호로 말하는 치어리더","original":"All-Cheering All the Time","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01972"],"summary":"치어리더 인물이 경기장 밖의 대화까지 구호와 박자로 표현하는 코미디 관습. 직업이나 활동을 인물의 유일한 말투로 확대해 성격을 빠르게 표시한다.","accent":"#7C808E","tab":"#A07A87","facet":"서술·언어·정보","bookmark":"문체·말투","entry_url":"cards/MEJE-KW-001231/index.html"},{"id":"MEJE-KW-001232","row_version":2,"title":"중국인은 모두 쿵푸를 안다는 고정관념","original":"All Chinese People Know Kung-Fu","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"중국계 인물이라면 누구나 쿵푸를 구사할 것처럼 그리는 표현 관습. 아시아인은 모두 무술을 안다는 고정관념의 한 변형이며 출신과 개인의 기술을 혼동한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001232/index.html"},{"id":"MEJE-KW-001233","row_version":1,"title":"실 하나로 풀리는 모든 옷","original":"All Cloth Unravels","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"천의 종류와 봉제 방식을 무시하고 한 가닥을 잡아당기면 옷 전체가 연속해서 풀리는 만화적 연출. 사물의 재질보다 빠른 변형과 웃음을 위해 쓰인다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001233/index.html"},{"id":"MEJE-KW-001234","row_version":1,"title":"모든 범죄에 같은 벌을 내리는 체제","original":"All Crimes Are Equal","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15","ML-T01347","ML-T01349"],"summary":"죄의 경중을 따지지 않고 사소한 위반과 중대한 범죄를 같은 강도로 처벌하는 가상 제도. 권력의 자의성과 불합리함을 드러내며 인물에게 저항의 이유를 준다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"처벌 제도","entry_url":"cards/MEJE-KW-001234/index.html"},{"id":"MEJE-KW-001235","row_version":3,"title":"죽음을 되돌릴 수 없는 세계","original":"All Deaths Final","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"마법이나 기술이 발달해도 죽은 존재를 원래대로 되살릴 수 없다는 세계관 규칙. 상실의 무게를 유지하고 부활을 찾는 여정의 한계를 분명히 한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001235/index.html"},{"id":"MEJE-KW-001236","row_version":2,"title":"모든 사막에 선인장을 놓는 연출","original":"All Deserts Have Cacti","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"지역과 기후가 다른 사막을 하나의 선인장 이미지로 표시하는 배경 관습. 빠른 장소 인식에는 편리하지만 서로 다른 사막의 생태를 지운다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001236/index.html"},{"id":"MEJE-KW-001237","row_version":2,"title":"모든 개가 순종으로 등장하는 관습","original":"All Dogs Are Purebred","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 개들이 대부분 뚜렷한 품종 외형을 가지며 혼종은 드물게 보이는 표현 관습. 알아보기 쉬운 디자인과 촬영상의 편의가 동물의 다양성을 좁힌다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001237/index.html"},{"id":"MEJE-KW-001238","row_version":1,"title":"드러머를 난폭한 원시인으로 그리는 관습","original":"All Drummers Are Animals","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"드럼 연주자를 리듬의 힘만 강조한 거칠고 통제하기 어려운 인물로 그리는 고정 이미지. 연주의 기술과 개별 음악가의 성격을 지우는 과장으로 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001238/index.html"},{"id":"MEJE-KW-001239","row_version":2,"title":"닮았다는 설정과 다른 두 인물의 외형","original":"Alleged Lookalikes","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"작품 속 인물들은 두 사람이 똑같이 생겼다고 말하지만 관객에게는 닮음이 잘 보이지 않는 상황. 배우 선택이나 캐릭터 구분을 위한 디자인과 이야기 속 설정이 어긋난다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001239/index.html"},{"id":"MEJE-KW-001240","row_version":1,"title":"연애를 못한다지만 관계가 계속 생기는 인물","original":"Allegedly Dateless","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"연애에 서툴다고 반복해서 소개되지만 화면에서는 꾸준히 만남과 관계를 맺는 인물형. 대사로 부여된 성격과 실제 사건의 누적이 충돌한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001240/index.html"},{"id":"MEJE-KW-001241","row_version":1,"title":"무료를 내세우지만 필수 결제를 요구하는 게임","original":"Allegedly Free Game","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"무료 참여를 광고하면서 핵심 진행이나 공정한 경쟁에는 유료 결제가 사실상 필요한 게임 운영 방식. 홍보 문구와 이용 경험 사이의 간격을 다룬다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001241/index.html"},{"id":"MEJE-KW-001242","row_version":2,"title":"의도와 달리 불편하게 읽히는 낙관적 결말","original":"Allegedly Optimistic Ending","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"창작자는 긍정적 해결로 제시했지만 관객은 남겨진 피해나 모순 때문에 불안한 결말로 받아들이는 경우. 이전 이야기를 무효로 만드는 후속 전개와 달리 한 결말 안에서 해석이 갈린다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001242/index.html"},{"id":"MEJE-KW-001243","row_version":1,"title":"충성의 대상을 공개적으로 확언하기","original":"Allegiance Affirmation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 말이나 행동으로 어느 편에 서는지 분명히 밝히는 사건. 모호했던 관계를 정리하거나 과거의 소속을 끊는 전환점이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001243/index.html"},{"id":"MEJE-KW-001244","row_version":1,"title":"개념을 대신 말하는 인물","original":"Allegorical Character","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00890"],"summary":"한 인물이 특정 가치나 집단, 사상을 대표하도록 설계되거나 작품 안에서 그렇게 읽히는 인물형. 인물의 개별성과 상징적 역할이 함께 존재할 수 있다. 서사 전체를 빌린 비유와는 범위가 다르다.","accent":"#7B7594","tab":"#778F70","facet":"인물","bookmark":"원형적 역할","entry_url":"cards/MEJE-KW-001244/index.html"},{"id":"MEJE-KW-001245","row_version":1,"title":"서사 전체를 빌린 비유","original":"Allegory","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물과 사건의 관계를 다른 사회적·철학적 문제에 대응시켜 이야기 전체로 뜻을 전하는 구성. 개별 상징 하나보다 여러 요소의 관계가 이어져 비유를 이룬다. 개념을 대신 말하는 인물은 그중 인물 한 명에 초점을 둔다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001245/index.html"},{"id":"MEJE-KW-001246","row_version":1,"title":"기존 이야기의 여정을 다시 겪기","original":"Allegory Adventure","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"인물이 이미 알려진 작품이나 전승과 비슷한 사건을 실제 여정에서 차례로 만나면서 두 이야기가 포개지는 구성. 단순한 장면 인용보다 여정의 구조가 겹치는 데 초점을 둔다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001246/index.html"},{"id":"MEJE-KW-001247","row_version":2,"title":"작은 선거도 운명을 건 대결로 그리기","original":"All Elections Are Serious Business","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"권한이 크지 않은 자리의 선거까지 인물과 공동체의 앞날을 바꿀 중대 사건처럼 그리는 전개. 선거의 실제 권한보다 경쟁의 감정과 관계 변화가 강조된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001247/index.html"},{"id":"MEJE-KW-001248","row_version":2,"title":"몸을 감싸는 권위의 망토","original":"All-Encompassing Mantle","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01436","ML-T01438"],"summary":"몸의 윤곽을 거의 드러내지 않을 만큼 넓게 두른 망토를 권력자나 수수께끼 인물의 표지로 쓰는 의상 관습. 실루엣과 움직임을 제한해 거리감과 위엄을 만든다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"망토","entry_url":"cards/MEJE-KW-001248/index.html"},{"id":"MEJE-KW-001249","row_version":1,"title":"악한 존재에 몸이 반응하는 능력","original":"Allergic to Evil","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"위험하거나 사악하다고 설정된 존재에 가까워지면 인물의 몸에 통증이나 불편함이 나타나는 초자연적 감지 능력. 실제 질병이나 도덕성을 진단하는 개념으로 쓰지 않는다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-001249/index.html"},{"id":"MEJE-KW-001250","row_version":1,"title":"사랑 앞에서 몸이 아픈 듯 반응하기","original":"Allergic to Love","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"호감을 느끼는 사람 앞에서 긴장과 두려움이 극단적인 신체 불편처럼 표현되는 인물 반응. 비유적 연출이며 실제 알레르기와 구분한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001250/index.html"},{"id":"MEJE-KW-001251","row_version":1,"title":"반복되는 일상을 견디지 못하는 인물","original":"Allergic to Routine","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"규칙적인 생활이 계속되면 스스로 변화를 만들지 않고는 못 배기는 인물형. 모험을 이끌 수 있지만 주변인의 안정과 선택을 흔들기도 한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001251/index.html"},{"id":"MEJE-KW-001252","row_version":1,"title":"소설처럼 정교하게 말하는 일인칭 화자","original":"All First-Person Narrators Write Like Novelists","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01926","ML-T01927"],"summary":"인물이 직접 겪은 일을 말한다는 설정인데도 문장과 장면 구성이 완성된 소설처럼 정교한 서술 관습. 화자의 자연스러운 말투와 독자를 위한 문학적 전달이 겹친다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"1인칭 화자","entry_url":"cards/MEJE-KW-001252/index.html"},{"id":"MEJE-KW-001253","row_version":2,"title":"비행 생물을 새처럼 그리기","original":"All Flyers Are Birds","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"새가 아닌 비행 생물에게도 둥지 짓기, 지저귀기, 나뭇가지에 앉기 같은 새의 습성을 부여하는 표현 관습. 동물의 감정을 개처럼 표현하기와 비슷하게 익숙한 동물의 행동으로 낯선 존재를 읽히게 한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001253/index.html"},{"id":"MEJE-KW-001254","row_version":2,"title":"이전 이야기를 무효로 만드는 후속 전개","original":"All for Nothing","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05","ML-T00611","ML-T00613"],"summary":"뒤늦은 전개가 앞선 인물의 선택이나 성취의 의미를 없애 버리는 서사 변화. 인물이 새 사건으로 성과를 잃는 경우와 과거의 사건 자체가 없었던 것으로 바뀌는 경우를 구분한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"전개","entry_url":"cards/MEJE-KW-001254/index.html"},{"id":"MEJE-KW-001255","row_version":2,"title":"동성애자와 아동 성범죄를 연결하는 혐오 관습","original":"All Gays Are Pedophiles","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"동성애를 아동 대상 성범죄와 근거 없이 연결해 인물을 위협으로 묘사하는 혐오 표현 관습. 성적 지향과 가해 행위는 별개이며 이 카드는 차별적 묘사를 식별하기 위한 것이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001255/index.html"},{"id":"MEJE-KW-001256","row_version":2,"title":"동성애자는 모두 문란하다는 고정관념","original":"All Gays are Promiscuous","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"동성애자라면 관계의 수나 방식이 모두 같을 것이라고 단정하는 표현 관습. 개인의 선택과 관계를 성적 지향만으로 설명하는 일반화를 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001256/index.html"},{"id":"MEJE-KW-001257","row_version":2,"title":"동성애자는 모두 공연을 좋아한다는 고정관념","original":"All Gays Love Theater","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"동성애자 인물의 취향과 직업을 무대 공연에 자동으로 연결하는 표현 관습. 관심 분야는 개인마다 다르며 취향으로 성적 지향을 추정할 수 없다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001257/index.html"},{"id":"MEJE-KW-001258","row_version":2,"title":"혼종 자손에게 양쪽 형질이 반씩 나타나기","original":"All Genes Are Codominant","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"서로 다른 종 사이에서 태어난 인물이 부모 각각의 외형과 능력을 정확히 절반씩 물려받는 가상 유전 규칙. 실제 유전 법칙보다 디자인의 이해와 균형을 우선한 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001258/index.html"},{"id":"MEJE-KW-001259","row_version":2,"title":"독일인을 나치와 동일시하는 관습","original":"All Germans Are Nazis","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"시대와 개인의 차이를 지우고 독일인 등장인물을 나치의 표지로만 그리는 표현 관습. 역사적 책임을 다루는 일과 국적 전체를 하나의 이념으로 환원하는 일을 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001259/index.html"},{"id":"MEJE-KW-001260","row_version":2,"title":"괴물 자녀가 다니는 학교","original":"All-Ghouls School","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"괴물이나 초자연 존재의 자녀가 또래와 함께 배우고 경쟁하는 학교 설정. 익숙한 학원 생활의 규칙과 각 존재의 능력·문화가 만나는 장소가 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001260/index.html"},{"id":"MEJE-KW-001261","row_version":2,"title":"여자아이는 모두 조랑말을 좋아한다는 관습","original":"All Girls Like Ponies","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"어린 여자 인물의 바람을 조랑말 한 가지로 표현하는 성별 고정 이미지. 취향과 계층, 생활 환경의 차이를 생략한 빠른 캐릭터 표지로 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001261/index.html"},{"id":"MEJE-KW-001262","row_version":2,"title":"여성은 거친 남성을 선호한다는 관습","original":"All Girls Want Bad Boys","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여성 인물의 호감을 위험하거나 무례한 남성에게 자동으로 향하게 하는 연애 표현 관습. 매력의 묘사와 상대를 해치는 행동을 낭만화하는 묘사를 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001262/index.html"},{"id":"MEJE-KW-001263","row_version":2,"title":"어느 행성이든 중력이 같게 그리기","original":"All Gravity Is the Same","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"크기와 환경이 다른 행성에서도 인물의 걷기와 점프가 지구와 똑같이 보이는 설정 관습. 세계의 물리 조건보다 관객이 익숙한 움직임을 우선한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001263/index.html"},{"id":"MEJE-KW-001264","row_version":2,"title":"성인이 된 옛 친구를 새롭게 바라보기","original":"\"All Grown Up\" Remark","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"어린 시절 알던 친구를 성인이 된 뒤 다시 만나 관계의 가능성을 새롭게 느끼는 재회 장면. 과거의 친밀감과 현재의 선택을 분리해 그리는 데 의미가 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001264/index.html"},{"id":"MEJE-KW-001265","row_version":2,"title":"치어리더는 남성의 선망 대상이라는 관습","original":"All Guys Want Cheerleaders","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"치어리더인 여성 인물이 남성 인물 모두의 관심을 끈다고 전제하는 표현 관습. 운동과 응원의 역할을 개인의 성격이나 선택보다 외모와 인기의 표지로 좁힌다. 여성 대학 동아리 구성원을 성적 대상으로 그리기와 인접하지만 무대가 다르다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001265/index.html"},{"id":"MEJE-KW-001266","row_version":2,"title":"여성 대학 동아리 구성원을 성적 대상으로 그리기","original":"All Guys Want Sorority Women","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여성 대학 동아리 구성원을 성적 매력과 인기만으로 설명하는 표현 관습. 집단의 활동이나 구성원마다 다른 목표는 가려지고 관객의 시선에 맞춘 이미지가 앞선다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001266/index.html"},{"id":"MEJE-KW-001267","row_version":4,"title":"멸망 뒤 남은 대중문화 상징의 신격화","original":"All Hail the Great God Mickey!","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"옛 문명의 기록이 사라진 뒤 남은 광고, 조각상이나 캐릭터를 후대 사회가 신성한 존재로 받아들이는 설정. 사물의 원래 뜻과 새 공동체가 부여한 뜻 사이의 간격이 세계관을 만든다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001267/index.html"},{"id":"MEJE-KW-001268","row_version":3,"title":"세력 관계를 수치로 표시하는 게임","original":"Alliance Meter","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02088","ML-T02093"],"summary":"플레이어의 행동에 따라 각 집단의 신뢰와 적대 정도가 달라지고 이를 수치나 단계로 보여 주는 게임 규칙. 한 세력과 가까워지는 선택이 다른 세력과의 관계를 바꿀 수 있다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"관계도 성장","entry_url":"cards/MEJE-KW-001268/index.html"},{"id":"MEJE-KW-001269","row_version":1,"title":"다른 세계의 동일 인물들이 결성한 동맹","original":"Alliance of Alternates","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 다른 세계에서 온 같은 인물의 여러 버전이 공동 목표를 위해 힘을 합치는 관계. 비슷한 출발점과 서로 다른 선택의 결과가 팀 내부 갈등과 협력의 재료가 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001269/index.html"},{"id":"MEJE-KW-001270","row_version":1,"title":"공동 복수를 위해 맺은 동맹","original":"Alliance of Revenge","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T01034","ML-T01042"],"summary":"같은 상대에게 해를 입은 인물들이 개별 복수를 접고 일시적으로 협력하는 관계. 목표는 같아도 피해의 성격과 원하는 결말은 서로 다를 수 있다. 상처 입은 여성들의 공동 대응은 구성원의 관계에 초점을 둔 별도 카드다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"임시 동맹","entry_url":"cards/MEJE-KW-001270/index.html"}]}.cards;